make_c <- function(){d<-read_input("function_trajectory.csv");ggplot(d,aes(month,estimate,color=group,fill=group))+annotate("rect",xmin=30,xmax=48,ymin=-Inf,ymax=Inf,fill="#F0F3F7")+geom_ribbon(aes(ymin=lower,ymax=upper),alpha=.12,color=NA)+geom_line(linewidth=.5)+geom_point(size=1.05)+scale_color_manual(values=c("Higher early PSAP"=CFG$red,"Remaining participants"=CFG$blue))+scale_fill_manual(values=c("Higher early PSAP"=CFG$red,"Remaining participants"=CFG$blue))+scale_x_continuous(breaks=c(0,12,24,36,48),limits=c(0,48),expand=expansion(mult=c(.015,.015)))+scale_y_continuous(limits=c(0,68),breaks=c(0,20,40,60),expand=expansion(mult=c(0,.01)))+annotate("text",x=24,y=61,label="Difference 14.78",size=mm_pt(CFG$font_pt),family=CFG$family)+labs(title="c  Function over follow-up",x="Months",y="WOMAC function (0-68)")+base_theme()}
